import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long k = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // best[i]: earliest index of the maximum of a[i..n-1].
        int[] best = new int[n];
        int at = n - 1;
        for (int i = n - 1; i >= 0; i--) {
            if (a[i] >= a[at]) at = i;
            best[i] = at;
        }
        StringBuilder out = new StringBuilder();
        for (long i = 0; i < n;) {
            int j = best[(int) i];
            if (out.length() > 0) out.append(' ');
            out.append(a[j]);
            i = j + k + 1;
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	k := nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// best[i]: earliest index of the maximum of a[i..n-1].
	best := make([]int, n)
	at := n - 1
	for i := n - 1; i >= 0; i-- {
		if a[i] >= a[at] {
			at = i
		}
		best[i] = at
	}
	var out []byte
	for i := int64(0); i < int64(n); {
		j := best[i]
		if len(out) > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, a[j], 10)
		i = int64(j) + k + 1
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
